// Env is generated by `wrangler types` for the calling Worker.
// The caller's wrangler.jsonc includes a service binding named OPERATOR_BROKER.

export async function executeThroughPrivateBroker(
  env: Env,
  input: { signedCapability: string; actionId: string; attemptId: string },
) {
  // Await the RPC. Do not fire-and-forget a committing call.
  return await env.OPERATOR_BROKER.execute(input);
}
